/** A hibernating signaling room for one approved pair of devices. */
export class LinkSignalRoom {
  constructor(private readonly state: DurableObjectState) {}

  async fetch(request: Request): Promise<Response> {
    const deviceId = request.headers.get("X-Nexus-Signal-Device") || "";
    if (!deviceId || request.headers.get("Upgrade")?.toLowerCase() !== "websocket") {
      return new Response("upgrade required", { status: 426 });
    }
    const pair = new WebSocketPair();
    const client = pair[0];
    const server = pair[1];
    for (const old of this.state.getWebSockets()) {
      if (old.deserializeAttachment() === deviceId) old.close(4000, "reconnected");
    }
    this.state.acceptWebSocket(server);
    server.serializeAttachment(deviceId);
    return new Response(null, { status: 101, webSocket: client });
  }

  async webSocketMessage(sender: WebSocket, message: string | ArrayBuffer): Promise<void> {
    if (typeof message !== "string" || message.length > 16_384) {
      sender.close(1009, "signaling frame too large");
      return;
    }
    let frame: Record<string, unknown>;
    try { frame = JSON.parse(message) as Record<string, unknown>; }
    catch { sender.close(1003, "invalid signaling frame"); return; }
    if (!frame || !["offer", "answer", "ice", "presence", "activity"].includes(String(frame.type))) {
      sender.close(1003, "unsupported signaling frame");
      return;
    }
    // File data never traverses the Worker. Activity reports contain a short
    // app label and duration, not window titles, URLs, or browser sites.
    if (frame.type === "activity") {
      if (typeof frame.app !== "string" || frame.app.length > 100 ||
          !Number.isFinite(frame.active_ms) || Number(frame.active_ms) < 0 ||
          Number(frame.active_ms) > 3_600_000 || Object.keys(frame).some(k => !["type", "app", "active_ms"].includes(k))) {
        sender.close(1003, "invalid activity frame");
        return;
      }
    }
    const senderId = sender.deserializeAttachment();
    for (const peer of this.state.getWebSockets()) {
      if (peer !== sender && peer.deserializeAttachment() !== senderId) peer.send(message);
    }
  }
}
